
(function () {
  "use strict";
  var els = {};
  var state = { program: null, all: [] };
  function $(sel) { return document.querySelector(sel); }
  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }
  function fmtPrice(n) {
    return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " \u20bd";
  }
  function plural(n, one, few, many) {
    var n10 = n % 10, n100 = n % 100;
    if (n10 === 1 && n100 !== 11) return one;
    if (n10 >= 2 && n10 <= 4 && (n100 < 10 || n100 >= 20)) return few;
    return many;
  }
  function cacheEls() {
    els.content = $("#pg-content");
    els.title = $("#pg-title");
    els.crumb = $("#pg-crumb-current");
    els.eyebrow = $("#pg-eyebrow");
    els.relatedSection = $("#pg-related-section");
    els.relatedGrid = $("#pg-related");
  }
  function getId() {
    var p = new URLSearchParams(window.location.search);
    var id = (p.get("id") || "").trim();
    return id;
  }
  function load() {
    var id = getId();
    if (!id) {
      renderNotFound();
      return;
    }
    fetch("data/programs.json?v=1.0-790", { cache: "no-cache" })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.json();
      })
      .then(function (data) {
        state.all = (data && data.programs) ? data.programs : [];
        var prog = null;
        for (var i = 0; i < state.all.length; i++) {
          if (state.all[i].id === id) { prog = state.all[i]; break; }
        }
        state.program = prog;
        if (!prog) {
          renderNotFound();
          return;
        }
        renderProgram(prog);
        renderRelated(prog);
      })
      .catch(function (err) {
        console.error("program: загрузка не удалась", err);
        renderError();
      });
  }
  function renderNotFound() {
    document.title = "Программа не найдена — Академия ДПО";
    if (els.title) els.title.textContent = "Программа не найдена";
    if (els.eyebrow) els.eyebrow.textContent = "Ошибка";
    if (els.content) {
      els.content.innerHTML =
        '<div class="pg-empty">' +
        '  <p class="pg-empty__text">Программа с таким идентификатором не найдена.</p>' +
        '  <a href="marketplace.html" class="btn btn--primary btn--sm">Перейти в каталог</a>' +
        '</div>';
    }
    if (els.relatedSection) els.relatedSection.hidden = true;
  }
  function renderError() {
    if (els.title) els.title.textContent = "Не удалось загрузить программу";
    if (els.content) {
      els.content.innerHTML =
        '<div class="pg-empty">' +
        '  <p class="pg-empty__text">Не удалось загрузить данные программы. Попробуйте обновить страницу.</p>' +
        '  <a href="marketplace.html" class="btn btn--primary btn--sm">Перейти в каталог</a>' +
        '</div>';
    }
    if (els.relatedSection) els.relatedSection.hidden = true;
  }
  function tagHtml(tag) {
    if (!tag) return "";
    var cls = "mp-card__tag";
    if (tag === "Хит") cls += " mp-card__tag--hit";
    else if (tag === "Скидка") cls += " mp-card__tag--sale";
    else if (tag === "Новинка") cls += " mp-card__tag--new";
    else if (tag === "Премиум") cls += " mp-card__tag--premium";
    return '<span class="' + cls + '">' + esc(tag) + '</span>';
  }
  function renderProgram(p) {
    document.title = p.title + " — Академия ДПО";
    if (els.title) els.title.textContent = p.title;
    if (els.eyebrow) els.eyebrow.textContent = p.category || "Программа ДПО";
    if (els.crumb) els.crumb.textContent = p.title;
    var priceHtml = '<span class="pg-price__current">' + fmtPrice(p.price) + '</span>';
    if (p.oldPrice && p.oldPrice > p.price) {
      var pct = Math.round((1 - p.price / p.oldPrice) * 100);
      priceHtml = '<span class="pg-price__old">' + fmtPrice(p.oldPrice) + '</span>' +
                  '<span class="pg-price__current">' + fmtPrice(p.price) + '</span>' +
                  '<span class="pg-price__discount">−' + pct + '%</span>';
    }
    var pData = encodeURIComponent(JSON.stringify({
      id: p.id, title: p.title, price: p.price, category: p.category, format: p.format
    }));
    var reviewsWord = plural(p.reviews || 0, "отзыв", "отзыва", "отзывов");
    var html =
      '<div class="pg-layout">' +
      '  <div class="pg-main">' +
      '    <div class="pg-head">' +
      '      <div class="pg-tags">' + tagHtml(p.tag) + '</div>' +
      '      <div class="pg-rating">' +
      '        <span class="pg-rating__stars" aria-hidden="true">★ ' + (p.rating || "—") + '</span>' +
      '        <span class="pg-rating__count">' + (p.reviews || 0) + ' ' + reviewsWord + '</span>' +
      '      </div>' +
      '    </div>' +
      '    <ul class="pg-meta">' +
      '      <li><span class="pg-meta__label">Формат обучения</span><span class="pg-meta__value">' + esc(p.format) + '</span></li>' +
      '      <li><span class="pg-meta__label">Длительность</span><span class="pg-meta__value">' + p.duration + ' ак. часов</span></li>' +
      '      <li><span class="pg-meta__label">Документ</span><span class="pg-meta__value">' + esc(p.docType) + '</span></li>' +
      '      <li><span class="pg-meta__label">Категория</span><span class="pg-meta__value">' + esc(p.category) + '</span></li>' +
      '    </ul>' +
      '    <div class="prose pg-desc">' +
      '      <h3>Описание программы</h3>' +
      '      <p>' + esc(p.description) + '</p>' +
      '      <h3>Что вы получите</h3>' +
      '      <ul>' +
      '        <li>Документ установленного образца: ' + esc(p.docType) + '.</li>' +
      '        <li>Объём программы — ' + p.duration + ' академических часов.</li>' +
      '        <li>Формат обучения: ' + esc(p.format) + '.</li>' +
      '        <li>Доступ к учебно-методическим материалам и аттестации.</li>' +
      '      </ul>' +
      '    </div>' +
      '  </div>' +
      '  <aside class="pg-aside">' +
      '    <div class="pg-buy">' +
      '      <div class="pg-price">' + priceHtml + '</div>' +
      '      <div class="pg-buy__actions">' +
      '        <button type="button" class="btn btn--ghost btn--block" data-add-cart data-program="' + pData + '">В корзину</button>' +
      '        <button type="button" class="btn btn--primary btn--block" data-buy-now data-program="' + pData + '">Купить</button>' +
      '      </div>' +
      '      <ul class="pg-buy__list">' +
      '        <li>Обучение по договору</li>' +
      '        <li>Документ гособразца</li>' +
      '        <li>Помощь менеджера</li>' +
      '      </ul>' +
      '    </div>' +
      '  </aside>' +
      '</div>';
    if (els.content) els.content.innerHTML = html;
    syncBuyButton(p.id);
    injectSchema(p);
  }
  function syncBuyButton(id) {
    if (!window.DpoCart || !window.DpoCart.has) return;
    var btn = els.content && els.content.querySelector("[data-add-cart]");
    if (btn && window.DpoCart.has(id)) {
      btn.classList.add("is-in-cart");
      btn.textContent = "В корзине ✓";
    }
  }
  function relatedCardHtml(p) {
    var tag = tagHtml(p.tag);
    var priceHtml = "";
    if (p.oldPrice) {
      priceHtml = '<span class="mp-card__old">' + fmtPrice(p.oldPrice) + '</span>';
    }
    var pData = encodeURIComponent(JSON.stringify({
      id: p.id, title: p.title, price: p.price, category: p.category, format: p.format
    }));
    return (
      '<article class="mp-card" data-id="' + esc(p.id) + '">' +
      '  <a class="mp-card__link" href="program.html?id=' + encodeURIComponent(p.id) + '" aria-label="' + esc(p.title) + '"></a>' +
      '  <div class="mp-card__top">' + tag +
      '    <span class="mp-card__rating" title="Рейтинг">★ ' + (p.rating || "—") + '</span>' +
      '  </div>' +
      '  <h3 class="mp-card__title">' + esc(p.title) + '</h3>' +
      '  <p class="mp-card__category">' + esc(p.category) + '</p>' +
      '  <ul class="mp-card__meta">' +
      '    <li>' + esc(p.format) + '</li>' +
      '    <li>' + p.duration + ' ак. ч.</li>' +
      '    <li>' + esc(p.docType) + '</li>' +
      '  </ul>' +
      '  <div class="mp-card__foot">' +
      '    <div class="mp-card__prices">' +
      '      <span class="mp-card__price">' + fmtPrice(p.price) + '</span>' +
      '      ' + priceHtml +
      '    </div>' +
      '    <div class="mp-card__actions">' +
      '      <button type="button" class="btn btn--ghost btn--sm mp-card__cart" data-add-cart data-program="' + pData + '">В корзину</button>' +
      '      <button type="button" class="btn btn--primary btn--sm mp-card__buy" data-buy-now data-program="' + pData + '">Купить</button>' +
      '    </div>' +
      '  </div>' +
      '</article>'
    );
  }
  function renderRelated(p) {
    if (!els.relatedGrid || !els.relatedSection) return;
    var same = state.all.filter(function (x) {
      return x.category === p.category && x.id !== p.id;
    });
    if (same.length < 4) {
      var extra = state.all.filter(function (x) {
        return x.category !== p.category && x.id !== p.id;
      });
      extra.sort(function (a, b) { return a.id < b.id ? -1 : 1; });
      for (var i = 0; i < extra.length && same.length < 4; i++) {
        same.push(extra[i]);
      }
    }
    if (same.length === 0) {
      els.relatedSection.hidden = true;
      return;
    }
    var list = same.slice(0, 4);
    var html = "";
    for (var j = 0; j < list.length; j++) {
      html += relatedCardHtml(list[j]);
    }
    els.relatedGrid.innerHTML = html;
    els.relatedSection.hidden = false;
  }
  function injectSchema(p) {
    var existing = document.getElementById("pg-schema");
    if (existing) existing.parentNode.removeChild(existing);
    var script = document.createElement("script");
    script.type = "application/ld+json";
    script.id = "pg-schema";
    var url = "https://dondgoklo-cyber.github.io/Pavelstark/program.html?id=" + encodeURIComponent(p.id);
    var schema = {
      "@context": "https://schema.org",
      "@type": "Course",
      "name": p.title,
      "description": p.description,
      "provider": {
        "@type": "EducationalOrganization",
        "name": "Академия ДПО",
        "sameAs": "https://dondgoklo-cyber.github.io/Pavelstark/"
      },
      "url": url,
      "aggregateRating": {
        "@type": "AggregateRating",
        "ratingValue": p.rating || 0,
        "reviewCount": p.reviews || 0
      }
    };
    schema.offers = {
      "@type": "Offer",
      "price": p.price,
      "priceCurrency": "RUB",
      "availability": "https://schema.org/InStock",
      "url": url
    };
    script.textContent = JSON.stringify(schema);
    document.head.appendChild(script);
  }
  function init() {
    cacheEls();
    if (!els.content) return;
    load();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
